    const host = hostOf2(url);
    if (existing.some((item) => item.url === url)) {
      return { tone: "warn", title: "\u0423\u0436\u0435 \u0434\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u043E", detail: host };
    }
